'use strict';
const $=s=>document.querySelector(s), main=$('#main'), key='wortreise-v1';
const fresh=()=>({solved:[],mistakes:[],completed:[],sessions:0,large:false,drafts:{}});
let state=fresh(), persistent=true, filter='Alle Stationen', quiz=null;
try{const saved=JSON.parse(localStorage.getItem(key));if(saved&&typeof saved==='object'){for(const k of ['solved','mistakes','completed'])if(Array.isArray(saved[k]))state[k]=saved[k].filter(x=>typeof x==='string');state.sessions=Number.isFinite(saved.sessions)?saved.sessions:0;state.large=saved.large===true;if(saved.drafts&&typeof saved.drafts==='object'&&!Array.isArray(saved.drafts))state.drafts=Object.fromEntries(Object.entries(saved.drafts).filter(([k,v])=>typeof v==='string'&&k.startsWith('lesen-')).map(([k,v])=>[k,v.slice(0,4000)]));}}catch{persistent=false}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save=()=>{try{localStorage.setItem(key,JSON.stringify(state))}catch{persistent=false}};
const all=lessons.flatMap(l=>l.qs.map((q,i)=>({q,id:l.id+'-'+i,lesson:l})));
const grammar=lessons.filter(l=>l.kind!=='reading');
const known=new Set(all.map(x=>x.id));state.solved=state.solved.filter(x=>known.has(x));state.mistakes=state.mistakes.filter(x=>known.has(x));state.completed=state.completed.filter(x=>lessons.some(l=>l.id===x));
const button=(text,action,secondary=false)=>`<button class="button ${secondary?'secondary':''}" data-action="${action}">${text}</button>`;
const card=l=>`<a class="lesson-card" href="#lernen/${l.id}"><span class="icon" aria-hidden="true">${l.icon}</span>${state.completed.includes(l.id)?'<span class="done">✓ Runde geschafft</span>':''}<h3>${l.title}</h3><p>${l.intro}</p><div class="card-bottom"><span>${l.kind==='reading'?l.level+' · ':''}${l.qs.length} Aufgaben</span><b aria-hidden="true">↗</b></div></a>`;
function home(){const next=grammar.find(l=>!state.completed.includes(l.id))||grammar[0];main.innerHTML=`<section class="hero"><div><div class="eyebrow">DEUTSCH FÜR DIE 5. KLASSE</div><h1>In jedem Wort steckt<br><span>ein Abenteuer.</span></h1><p>Entdecke Grammatik und Geschichten, löse kleine Rätsel und wachse über dich hinaus. Schritt für Schritt, in deinem Tempo.</p><a class="button" href="#lernen/${next.id}">${state.completed.length?'Weiterlernen':'Meine Reise starten'} <span aria-hidden="true">→</span></a></div><div class="landscape" role="img" aria-label="Ein Fuchs begleitet dich durch eine Wortlandschaft mit Nomen, Verben und Adjektiven"><span class="sun"></span><span class="cloud">☁</span><img class="mascot" src="fips.svg" alt="" width="126" height="126"><span class="word one">der Fuchs</span><span class="word two">entdecken</span><span class="word three">neugierig</span><span class="bubble">✦</span></div></section><section class="journey-strip" aria-label="Dein Lernfortschritt"><div><strong>Deine Reise. Dein Tempo.</strong><p>Alle Stationen sind offen. Fang einfach an.</p></div><div class="mini-progress">${state.completed.length} von ${lessons.length} Stationen erkundet<progress max="${lessons.length}" value="${state.completed.length}" aria-label="Erkundete Stationen"></progress></div><a href="#fortschritt">Meine Erfolge ↗</a></section><section><div class="section-head"><div><h2>Deine Grammatik-Stationen</h2><p>Erst verstehen. Dann ausprobieren. Und immer dazulernen.</p></div><span>12 Stationen · 72 Aufgaben</span></div><div class="filters" aria-label="Themen filtern">${['Alle Stationen','Wörter entdecken','Sätze verstehen','Sicher schreiben'].map(f=>`<button class="chip" data-filter="${f}" aria-pressed="${filter===f}">${f}</button>`).join('')}</div><div class="lesson-grid" id="cards">${grammar.filter(l=>filter==='Alle Stationen'||l.group===filter).map(card).join('')}</div></section><section class="reading-invite"><div><span class="eyebrow">LESEN & VERSTEHEN</span><h2>Eine Geschichte. Viele Entdeckungen.</h2><p>Lies spannende Geschichten, knacke Wort-Rätsel und werde zum Textdetektiv. Sechs Texte in drei Stufen warten auf dich.</p><a class="button" href="#lesen">Zu den Leseübungen →</a></div><span class="reading-symbol" aria-hidden="true">📖</span></section><aside class="encourage"><span aria-hidden="true">🦊</span><div><h3>„Noch nicht“ ist der Anfang von „Ich kann das!“</h3><p>Ich bin Fips. Wenn etwas knifflig wird, bekommst du einen Tipp. Fehler gehören zur Reise dazu.</p></div></aside>`;}
function learn(id){const l=lessons.find(x=>x.id===id);if(!l)return missing();if(l.kind==='reading')return readingLesson(l);main.innerHTML=`<a class="back" href="#start">← Alle Lernstationen</a><div class="page-title"><div class="eyebrow">${l.group}</div><h1>${l.icon} ${l.title}</h1><p>${l.intro}</p></div><div class="learn-layout"><article class="lesson-body">${WortreiseLanguage.panel(id)}<h2>So funktioniert’s</h2><p>${l.rule}</p><div class="example">${l.example}</div><details><summary>Noch genauer erklärt</summary><p>${l.more}</p></details><div class="actions" style="margin-top:28px">${button('Jetzt üben →','practice:'+id)}</div>${WortreiseSpeech.panel(id)}<p class="notice">6 Aufgaben. Ohne Zeitlimit. Mit einer Erklärung nach jeder Antwort.</p></article><aside><div class="tip"><h3>💡 Fips’ Merktipp</h3><p>${l.tip}</p></div><p class="quiet">Du darfst jederzeit nachlesen oder eine Aufgabe noch einmal versuchen.</p></aside></div>`;}
function playground(){main.innerHTML=`<div class="page-title"><div class="eyebrow">SPIELWIESE</div><h1>Kopf an. Abenteuer los!</h1><p>Mische dein Wissen oder übe genau das, was noch knifflig ist. Ohne Stoppuhr und ohne verlorene Leben.</p></div><div class="lesson-grid"><article class="lesson-card"><span class="icon">🎲</span><h2>Wörter-Wundertüte</h2><p>8 zufällige Aufgaben aus allen Themen. Jede Runde ist eine neue Mischung.</p>${button('Quiz starten','mixed')}</article><article class="lesson-card"><span class="icon">🔎</span><h2>Knifflige Wörter</h2><p>${state.mistakes.length?`${state.mistakes.length} Aufgaben warten darauf, dass du sie noch einmal entdeckst.`:'Hier landen Aufgaben, die beim ersten Versuch noch nicht geklappt haben.'}</p>${state.mistakes.length?button('Gezielt wiederholen','review'):'<a class="button secondary" href="#start">Station aussuchen</a>'}</article><article class="lesson-card"><span class="icon">🌟</span><h2>Die Tagesportion</h2><p>5 abwechslungsreiche Aufgaben. Eine kleine Lernpause passt in jeden Tag.</p>${button('5 Aufgaben spielen','daily')}</article></div><aside class="encourage"><span>🦊</span><div><h3>Sterne sammelst du mit Wissen.</h3><p>Für jede erstmals richtig gelöste Aufgabe gibt es einen Wissensstern. Wiederholen lohnt sich auch ohne neue Sterne.</p></div></aside>`;}
function knowledge(){main.innerHTML=`<div class="page-title"><div class="eyebrow">DEIN GRAMMATIK-HEFT</div><h1>Nachschlagen macht schlau.</h1><p>Alle Regeln und Beispiele an einem Ort. Such nach einem Thema, einem Fachwort oder einem Beispiel.</p></div><div class="search"><label for="search">Was möchtest du wissen?</label><input id="search" type="search" placeholder="Zum Beispiel: Dativ, Verben, Zeitformen"></div><button class="button secondary small" data-action="print">Lernheft drucken</button><p id="count" class="quiet" role="status"></p><div id="knowledge" class="knowledge"></div>`;drawKnowledge('');$('#search').addEventListener('input',e=>drawKnowledge(e.target.value));}
function drawKnowledge(term){let ls=grammar.filter(l=>(l.title+' '+l.rule+' '+l.more+' '+l.example).toLocaleLowerCase('de').includes(term.trim().toLocaleLowerCase('de')));$('#count').textContent=ls.length+' Themen gefunden';$('#knowledge').innerHTML=ls.length?ls.map(l=>`<article><h2>${l.icon} ${l.title}</h2>${WortreiseLanguage.panel(l.id)}<p>${l.rule}</p><div class="example">${l.example}</div><p>${l.more}</p><a href="#lernen/${l.id}">Dieses Thema üben →</a></article>`).join(''):'<p>Kein Thema gefunden. Versuche einen kürzeren Suchbegriff, zum Beispiel „Verb“ oder „Fall“.</p>';}
function progress(){main.innerHTML=`<div class="page-title"><div class="eyebrow">MEINE ERFOLGE</div><h1>Schau, was du schon kannst.</h1><p>Jeder kleine Schritt zählt. Deine Erfolge bleiben in diesem Browser gespeichert, soweit die Browsereinstellungen das erlauben.</p></div><div class="stats"><div class="stat"><b>${state.solved.length} / ${all.length}</b><span>Wissenssterne</span></div><div class="stat"><b>${state.completed.length} / ${lessons.length}</b><span>Stationen erkundet</span></div><div class="stat"><b>${state.sessions}</b><span>Runden geschafft</span></div></div><h2>Deine Reiseabzeichen</h2><div class="badge-list">${[[1,'🌱','Erster Schritt','Löse eine Aufgabe richtig.'],[12,'🔎','Wortentdecker','Sammle 12 Wissenssterne.'],[36,'🧭','Sprachforscher','Sammle 36 Wissenssterne.'],[72,'📚','Wissenssammler','Sammle 72 Wissenssterne.'],[all.length,'🏆','Sprachprofi','Sammle alle '+all.length+' Wissenssterne.']].map(([n,i,t,d])=>`<div class="badge ${state.solved.length<n?'unearned':''}"><strong>${i} ${t}</strong><span>${state.solved.length>=n?'✓ Geschafft!':d}</span></div>`).join('')}</div><h2 style="margin-top:38px">Deine Stationen</h2><div class="lesson-grid">${lessons.map(card).join('')}</div><div class="actions" style="margin-top:30px">${state.mistakes.length?button('Knifflige Aufgaben wiederholen','review'):'<a class="button" href="#start">Weiter entdecken →</a>'}<a href="#speicher">Speicherung verwalten</a></div>`;}
function info(){main.innerHTML=`<a class="back" href="#start">← Zur Lernreise</a><div class="page-title"><h1>Gemeinsam sicherer werden.</h1><p>Für Eltern und Lehrkräfte: Wortreise unterstützt Kinder der 5. Klasse beim Aufbau deutscher Grammatik und beim Lesen und Verstehen von Texten.</p></div><div class="knowledge"><h2>Ein kleiner Lernrhythmus</h2><ol><li>Ein Thema auswählen und die Erklärung gemeinsam lesen.</li><li>Das Beispiel mit eigenen Worten erklären lassen.</li><li>Die sechs Aufgaben selbstständig bearbeiten.</li><li>Bei Fehlern den Tipp besprechen und später wiederholen.</li></ol><h2>Was die Website bietet</h2><p>Zwölf Grammatikthemen und sechs Lesetexte mit zusammen 108 Aufgaben, Auswahlfragen und kurzen Texteingaben. Die Leseübungen umfassen Geschichten, einen Sachtext und eine Schulmitteilung in drei Stufen. Zu jedem Text gibt es Worterklärungen und einen freiwilligen Schreibauftrag mit Selbstkontrolle. Freie Schreibtexte werden nicht automatisch bewertet. Jede Antwort bekommt eine fachliche Erklärung. Alle Stationen sind frei zugänglich. Es gibt keine Rangliste, keinen Zeitdruck und keine Strafe für Fehler.</p><h2>Passend begleiten</h2><p>Die Inhalte decken verbreitete Grammatik-Grundlagen ab. Die Reihenfolge und die Fachbegriffe können je nach Schule und Lehrwerk abweichen. Bei größeren Lücken hilft es, mit Wortarten zu beginnen und nur eine Station auf einmal zu bearbeiten. Die Aufgaben ersetzen keine individuelle Lernstandsdiagnose.</p><h2>Erklärungen in anderen Sprachen</h2><p>Über „Erklärungssprache“ gibt es zusätzliche Erklärungen zu allen zwölf Grammatikthemen und Lesetipps zu allen sechs Texten auf Englisch, Türkisch, Arabisch und Ukrainisch. Die Sprachhilfe zum Thema steht auch in den Übungen und im Nachschlageheft bereit. Die übersetzten Sprachhilfen lassen sich direkt im jeweiligen Audioplayer anhören. Aufgaben, Antwortbegründungen, Beispiele und Miriams Aufnahmen bleiben auf Deutsch. Die Auswahl lässt sich jederzeit ändern.</p><h2>Hilfen beim Lesen</h2><p>Mit A+ lässt sich die Schrift vergrößern. Alle zwölf Grammatikstationen und sechs Lesetexte können mit der KI-Stimme Miriam vorgelesen werden. Das Tempo ist einstellbar; die Aufnahme lässt sich pausieren und fortsetzen. Die Website lässt sich mit der Tastatur bedienen. Das Nachschlageheft kann über die Druckfunktion ausgedruckt werden.</p><h2>Auf gemeinsam genutzten Geräten</h2><p>Der Fortschritt gehört zu diesem Browser, nicht zu einem persönlichen Konto. Mehrere Kinder im selben Browser teilen den Fortschritt. Verwenden Sie getrennte Browserprofile oder setzen Sie ihn vor einem Wechsel zurück.</p><a class="button" href="#wissen">Zum Lernheft →</a></div>`;}
function storage(){main.innerHTML=`<a class="back" href="#start">← Zur Lernreise</a><div class="page-title"><h1>Dein Fortschritt bleibt bei dir.</h1><p>Wortreise speichert gelöste Aufgaben, Wiederholungen, abgeschlossene Runden, freiwillige Schreibentwürfe und die Schriftgröße lokal in diesem Browser.</p></div><div class="knowledge"><h2>Keine Namen nötig</h2><p>Die Lernanwendung fragt keine Namen, E-Mail-Adressen oder Passwörter ab und verwendet keine Analyse- oder Werbedienste. Der Hosting-Anbieter kann beim Aufruf technisch notwendige Verbindungsdaten verarbeiten. Die Lernwebsite ist ohne Anmeldung zugänglich.</p><h2>Was du wissen solltest</h2><p>Der Lernstand wird nicht auf andere Geräte übertragen. Wenn du die Browserdaten löschst, geht er verloren. Im privaten Modus bleibt er möglicherweise nur bis zum Schließen des Browsers erhalten.</p><p>${persistent?'Die lokale Speicherung ist verfügbar.':'Die lokale Speicherung ist nicht verfügbar. Dein Fortschritt gilt nur für die aktuelle Sitzung.'}</p><h2>Vorlesen</h2><p>Die freiwillige Vorlesefunktion spielt fertige Audioaufnahmen mit der KI-Stimme Miriam ab. Die Dateien werden direkt von dieser Website geladen. Dabei werden keine eigenen Texte oder Schreibentwürfe an einen Sprachdienst gesendet. Dein Vorlesetempo wird lokal in diesem Browser gespeichert.</p><h2>Erklärungssprache</h2><p>Deine gewählte Erklärungssprache wird lokal in diesem Browser gespeichert. Die Sprachhilfen und ihre KI-Vorleseaufnahmen auf Englisch, Türkisch, Arabisch und Ukrainisch sind fertig hinterlegt und werden direkt von dieser Website geladen. Dafür werden keine Antworten oder Schreibentwürfe an einen Übersetzungsdienst gesendet. Auf gemeinsam genutzten Geräten kannst du die Sprache oben jederzeit wechseln.</p><h2>Neu anfangen</h2><p>Damit entfernst du die gespeicherten Sterne, Wiederholungen, Schreibentwürfe und Runden dieses Browsers.</p>${button('Lernfortschritt zurücksetzen','reset-ask',true)}<div id="reset-confirm"></div></div>`;}
function shuffled(xs){let a=[...xs];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a;}
function startQuiz(items,title,lessonId=null){quiz={items,index:0,title,lessonId,correct:0,answered:false,selected:null,wrong:[]};location.hash='quiz';if(location.hash==='#quiz')renderQuiz();}
function renderQuiz(){if(!quiz||quiz.index>=quiz.items.length)return playground();const {q,lesson}=quiz.items[quiz.index];quiz.answered=false;quiz.selected=null;const choice=Array.isArray(q[1]);main.innerHTML=`<div class="exercise"><a class="back" href="${quiz.lessonId?'#lernen/'+quiz.lessonId:'#spiel'}">← Übung verlassen und nachlesen</a><div class="exercise-top"><span>${quiz.title}</span><span>Aufgabe ${quiz.index+1} von ${quiz.items.length}</span></div><progress value="${quiz.index}" max="${quiz.items.length}" aria-label="Fortschritt dieser Übungsrunde"></progress>${FipsGuide.question(quiz.items[quiz.index])}<section class="question-panel"><p class="eyebrow">${lesson.title}</p><h1>${esc(q[0])}</h1>${lesson.kind==='reading'?quizPassage(lesson):''}${WortreiseLanguage.panel(lesson.id,true)}<form id="answer-form">${choice?`<div class="answers" role="group" aria-label="Antwort auswählen">${q[1].map((a,i)=>`<button class="answer" type="button" data-answer="${i}" aria-pressed="false">${esc(a)}</button>`).join('')}</div>`:'<label for="answer-input">Deine Antwort</label><input id="answer-input" autocomplete="off" autocapitalize="off" spellcheck="false"><p class="quiet">Ein Wort genügt. Umlaute bitte als ä, ö oder ü schreiben.</p>'}<div id="feedback" class="feedback" role="status" aria-live="polite"></div><div class="actions"><button id="check" class="button" type="submit">Antwort prüfen</button><button type="button" class="button secondary" data-action="hint">💡 Tipp</button><button type="button" class="button secondary" data-action="skip">Noch unsicher</button></div><p id="hint" class="notice" role="status"></p></form></section></div>`;$('#answer-form').addEventListener('submit',check);WortreiseLanguage.mount();}
const normal=s=>s.trim().normalize('NFC').toLocaleLowerCase('de').replace(/[.!?]+$/,'');
function check(e){e.preventDefault();if(!quiz||quiz.answered)return;const item=quiz.items[quiz.index],q=item.q,choice=Array.isArray(q[1]);let answer=choice?quiz.selected:$('#answer-input').value;if(answer===null||(!choice&&!answer.trim())){$('#feedback').textContent='Wähle zuerst eine Antwort oder schreibe ein Wort in das Feld.';return}let correct=choice?answer===q[2]:(/^[.!?]$/.test(q[1])?answer.trim()===q[1]:normal(answer)===normal(q[1]));if(item.id==='gross-4')correct=answer.trim()==='Hund';finishAnswer(correct,false);}
function finishAnswer(correct,skip){if(!quiz||quiz.answered)return;quiz.answered=true;const item=quiz.items[quiz.index],q=item.q,choice=Array.isArray(q[1]);if(correct){quiz.correct++;if(!state.solved.includes(item.id))state.solved.push(item.id);state.mistakes=state.mistakes.filter(x=>x!==item.id)}else{quiz.wrong.push(item);if(!state.mistakes.includes(item.id))state.mistakes.push(item.id)}save();const solution=choice?q[1][q[2]]:q[1],explain=choice?q[3]:q[2];$('#feedback').classList.toggle('correct',correct);$('#feedback').innerHTML=`<strong>${correct?'✓ Genau richtig!':skip?'Wir schauen es uns gemeinsam an.':'Noch nicht ganz. Du lernst gerade dazu.'}</strong>${correct?'':`<p>Die Lösung ist: <b>${esc(solution)}</b></p>`}<p>${esc(explain)}</p>`;document.querySelectorAll('.answer').forEach((b,i)=>{b.disabled=true;if(choice&&i===q[2])b.classList.add('right')});if($('#answer-input'))$('#answer-input').disabled=true;$('#check').outerHTML=button(quiz.index===quiz.items.length-1?'Ergebnis ansehen →':'Nächste Aufgabe →','next');document.querySelector('[data-action="skip"]').disabled=true;document.querySelector('[data-action="hint"]').disabled=true;document.querySelector('[data-action="next"]').focus();}
function result(){state.sessions++;if(quiz.lessonId&&!state.completed.includes(quiz.lessonId))state.completed.push(quiz.lessonId);save();main.innerHTML=`<section class="result"><div class="medal" aria-hidden="true">${quiz.correct===quiz.items.length?'🏆':'🌟'}</div><h1>Eine Runde weiter!</h1><p>Du hast <strong>${quiz.correct} von ${quiz.items.length} Aufgaben</strong> richtig gelöst und dir alle Erklärungen angesehen.</p><p>${quiz.wrong.length?'Was noch schwierig war, wartet in deiner Wiederholung. Mit jedem Versuch wird es vertrauter.':'Das hast du gut gemacht! Du kannst ein neues Thema entdecken oder dein Wissen bunt mischen.'}</p><div class="actions">${quiz.wrong.length?button('Diese Aufgaben wiederholen','retry'):''}<a class="button ${quiz.wrong.length?'secondary':''}" href="${quiz.lessonId?.startsWith('lesen-')?'#lesen':'#start'}">${quiz.lessonId?.startsWith('lesen-')?'Zu den Lesetexten':'Zur Lernreise'}</a><a href="#fortschritt">Meine Erfolge</a></div><p class="quiet">Insgesamt ${state.solved.length} von ${all.length} Wissenssternen gesammelt.</p>${FipsGuide.page("result")}</section>`;WortreiseLanguage.mount();focusMain();}
function missing(){main.innerHTML='<h1>Diese Station gibt es nicht.</h1><a class="button" href="#start">Zur Lernreise</a>';}
function focusMain(){main.focus({preventScroll:true});window.scrollTo(0,0)}
function route(){WortreiseSpeech.stop();const [page,id]=(location.hash.slice(1)||'start').split('/');if(page==='main'){focusMain();return;}document.querySelectorAll('nav a').forEach(a=>{let section=page==='lernen'?(id?.startsWith('lesen-')?'lesen':'start'):page;let active=a.hash==='#'+section;if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});({start:home,lesen:readingHome,lernen:()=>learn(id),spiel:playground,wissen:knowledge,fortschritt:progress,info,speicher:storage,quiz:renderQuiz}[page]||missing)();if(page!=='quiz'){const anchor=main.querySelector('.page-title, .hero');if(anchor)anchor.insertAdjacentHTML('afterend',FipsGuide.page(page,lessons.find(l=>l.id===id)));}WortreiseLanguage.mount();WortreiseSpeech.refresh();focusMain();}
main.addEventListener('click',e=>{const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===f));$('#cards').innerHTML=grammar.filter(l=>filter==='Alle Stationen'||l.group===filter).map(card).join('');return}const a=e.target.closest('[data-answer]');if(a&&quiz&&!quiz.answered){quiz.selected=Number(a.dataset.answer);document.querySelectorAll('[data-answer]').forEach(b=>{b.classList.toggle('selected',b===a);b.setAttribute('aria-pressed',b===a)});return}const b=e.target.closest('[data-action]');if(!b)return;const [action,id]=b.dataset.action.split(':');if(action==='practice'){const l=lessons.find(x=>x.id===id);startQuiz(all.filter(x=>x.lesson.id===id),l.title,id)}if(action==='mixed')startQuiz(shuffled(all).slice(0,8),'Wörter-Wundertüte');if(action==='daily')startQuiz(shuffled(all).slice(0,5),'Deine Tagesportion');if(action==='review'){const items=shuffled(all.filter(x=>state.mistakes.includes(x.id)));if(items.length)startQuiz(items,'Deine Wiederholung');else playground()}if(action==='retry')startQuiz([...quiz.wrong],'Noch einmal entdecken');if(action==='hint'&&quiz)$('#hint').textContent=quiz.items[quiz.index].lesson.tip;if(action==='skip')finishAnswer(false,true);if(action==='next'&&quiz&&quiz.answered){quiz.index++;if(quiz.index===quiz.items.length)result();else{renderQuiz();focusMain()}}if(action==='print')window.print();if(action==='reset-ask')$('#reset-confirm').innerHTML=`<div class="feedback"><p>Alle Lernfortschritte dieses Browsers wirklich löschen? Das lässt sich nicht rückgängig machen.</p><div class="actions">${button('Ja, Fortschritt löschen','reset')}${button('Behalten','cancel-reset',true)}</div></div>`;if(action==='cancel-reset')$('#reset-confirm').innerHTML='';if(action==='reset'){const large=state.large;state=fresh();state.large=large;quiz=null;save();$('#reset-confirm').innerHTML='<p role="status">Dein Lernfortschritt wurde zurückgesetzt. Du kannst neu loslegen.</p>'}});
let readingLevel='Alle Stufen';
const passage=l=>`<div class="passage">${l.paragraphs.map((p,i)=>`<p><span class="paragraph-number" aria-label="Absatz ${i+1}">${i+1}</span>${esc(p)}</p>`).join('')}</div>`;

function readingHome(){
 const finished=readings.filter(l=>state.completed.includes(l.id)).length;
 main.innerHTML=`<div class="page-title"><div class="eyebrow">DEINE LESEWELT</div><h1>Lies dich ins nächste Abenteuer.</h1><p>Geschichten entdecken, Wörter verstehen und zwischen den Zeilen lesen. Hier zählt genaues Lesen, nicht Geschwindigkeit.</p></div><div class="reading-steps" aria-label="So übst du"><div><b>1. In Ruhe lesen</b><p>Lies einen Absatz nach dem anderen.</p></div><div><b>2. Genau hinschauen</b><p>Worterklärungen und Textstellen helfen dir.</p></div><div><b>3. Ausprobieren</b><p>Löse sechs Aufgaben. Nachlesen ist erlaubt!</p></div></div><div class="section-head"><div><h2>Welchen Text entdeckst du heute?</h2><p>Starte leicht oder wähle direkt einen längeren Text.</p></div><span>${finished} von ${readings.length} Texten erkundet</span></div><div class="filters" aria-label="Lesestufe auswählen">${['Alle Stufen','Leichter Einstieg','Weiter entdecken','Genau hinschauen'].map(level=>`<button class="chip" data-reading-level="${level}" aria-pressed="${readingLevel===level}">${level}</button>`).join('')}</div><div id="reading-cards" class="lesson-grid">${readings.filter(l=>readingLevel==='Alle Stufen'||l.level===readingLevel).map(readingCard).join('')}</div><p class="quiet" id="reading-count" role="status">${readings.filter(l=>readingLevel==='Alle Stufen'||l.level===readingLevel).length} Texte zur Auswahl</p><details class="reading-strategies"><summary>Fips’ Lesetricks: So verstehst du einen Text besser</summary><ol><li><strong>Vor dem Lesen:</strong> Schau auf die Überschrift. Worum könnte es gehen?</li><li><strong>Beim Lesen:</strong> Halte nach jedem Absatz kurz an. Was ist passiert? Was hast du erfahren?</li><li><strong>Unbekannte Wörter:</strong> Lies den Satz davor und danach. Schau in die Worterklärungen.</li><li><strong>Bei Fragen:</strong> Suche eine passende Textstelle. Unterscheide, was im Text steht und was du vermutest.</li><li><strong>Danach:</strong> Erzähle das Wichtigste in eigenen Worten. Drei Sätze reichen für den Anfang.</li></ol></details>`;
}
function readingCard(l){return `<a class="lesson-card" href="#lernen/${l.id}"><span class="icon" aria-hidden="true">${l.icon}</span>${state.completed.includes(l.id)?'<span class="done">✓ Runde geschafft</span>':''}<p class="reading-meta">${l.genre} · ${l.paragraphs.join(' ').split(/\s+/).length} Wörter</p><h3>${l.title}</h3><p>${l.intro}</p><div class="card-bottom"><span>${l.level}<br>6 Aufgaben + Schreibidee</span><b aria-hidden="true">↗</b></div></a>`;}
function readingLesson(l){
 main.innerHTML=`<a class="back" href="#lesen">← Alle Lesetexte</a><div class="page-title"><div class="eyebrow">${l.level} · ${l.genre}</div><h1>${l.icon} ${l.title}</h1><p>${l.intro}</p></div><div class="learn-layout reading-layout"><article class="lesson-body"><h2>Dein Lesetext</h2>${WortreiseSpeech.panel(l.id)}<div class="actions reading-tools">${button('Text drucken','print',true)}</div>${passage(l)}<div class="actions">${button('Leseaufgaben starten →','practice:'+l.id)}</div><p class="notice">6 Aufgaben mit Lösungen und Textbelegen. Du kannst bei jeder Frage im Text nachsehen.</p><details class="writing-task"><summary>Schreibidee: Jetzt bist du dran</summary>${FipsGuide.writing()}<p>${esc(l.writing)}</p><label for="writing-draft">Dein Entwurf (freiwillig)</label><textarea id="writing-draft" rows="5" maxlength="4000" data-draft="${l.id}" aria-describedby="draft-note">${esc(state.drafts[l.id]||'')}</textarea><p id="draft-note" class="notice">Dein Entwurf bleibt in diesem Browser. Bitte schreibe keine privaten Daten hinein. Es gibt keine automatische Bewertung.</p><p id="draft-status" class="notice" role="status"></p><details><summary>Selbstkontrolle für deinen Text</summary><ul><li>Habe ich die Schreibaufgabe beantwortet?</li><li>Kann ich meine Aussagen mit dem Lesetext begründen?</li><li>Habe ich vollständige Sätze geschrieben?</li><li>Beginnen meine Sätze groß und enden sie mit einem Satzzeichen?</li></ul><p>Du kannst deinen Text zusätzlich einer Lehrkraft oder einer vertrauten Person zeigen.</p></details></details></article><aside>${WortreiseLanguage.panel(l.id)}<div class="tip"><h2 class="side-heading">💡 Fips’ Lesetipp</h2><p>${esc(l.tip)}</p></div><section class="vocabulary"><h2 class="side-heading">Wörter verstehen</h2><dl>${l.vocab.map(([word,meaning])=>`<dt>${esc(word)}</dt><dd>${esc(meaning)}</dd>`).join('')}</dl></section><p class="quiet">Alle Texte wurden für Wortreise geschrieben. Lies sie gern mehrmals, auch laut oder gemeinsam mit jemandem.</p></aside></div>`;
}
function quizPassage(l){return `<details class="quiz-passage" open><summary>Im Lesetext nachschauen: ${esc(l.title)}</summary>${passage(l)}<details><summary>Worterklärungen anzeigen</summary><dl>${l.vocab.map(([w,m])=>`<dt>${esc(w)}</dt><dd>${esc(m)}</dd>`).join('')}</dl></details></details>`;}
main.addEventListener('click',e=>{const b=e.target.closest('[data-reading-level]');if(!b)return;readingLevel=b.dataset.readingLevel;document.querySelectorAll('[data-reading-level]').forEach(x=>x.setAttribute('aria-pressed',x===b));const filtered=readings.filter(l=>readingLevel==='Alle Stufen'||l.level===readingLevel);$('#reading-cards').innerHTML=filtered.map(readingCard).join('');$('#reading-count').textContent=filtered.length+' Texte zur Auswahl';});
main.addEventListener('input',e=>{if(!e.target.matches('[data-draft]'))return;state.drafts[e.target.dataset.draft]=e.target.value.slice(0,4000);save();$('#draft-status').textContent=persistent?'Entwurf in diesem Browser gespeichert.':'Speichern ist nicht möglich. Kopiere deinen Entwurf, bevor du die Seite schließt.';});

$('#read-size').addEventListener('click',()=>{state.large=!state.large;setSize();save()});function setSize(){document.documentElement.classList.toggle('large',state.large);$('#read-size').setAttribute('aria-pressed',state.large);$('#read-size').setAttribute('aria-label',state.large?'Normale Schriftgröße einschalten':'Größere Schrift einschalten')}setSize();window.addEventListener('hashchange',route);route();
